DROP TABLE IF EXISTS `ai_playerbot_locks`;
CREATE TABLE `ai_playerbot_locks` (
  `name_id` MEDIUMINT(8) NOT NULL AUTO_INCREMENT,
  `gearlock` BIT(1) NOT NULL DEFAULT b'0',
  PRIMARY KEY (`name_id`)
) ENGINE=InnoDB 
  AUTO_INCREMENT=1 
  DEFAULT CHARSET=utf8mb4 
  COLLATE=utf8mb4_general_ci 
  COMMENT='Playerbot locks' 
  ROW_FORMAT=Dynamic;

DROP TABLE IF EXISTS `ai_playerbot_names`;
CREATE TABLE `ai_playerbot_names` (
  `name_id` MEDIUMINT(8) NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `gender` TINYINT(3) UNSIGNED NOT NULL,
  `race` SMALLINT(5) UNSIGNED NOT NULL,
  `class` SMALLINT(5) UNSIGNED NOT NULL,
  `purpose` INT(11) UNSIGNED NOT NULL,
  `priority` BIT(1) NOT NULL,
  `in_use` BIT(1) NOT NULL,
  PRIMARY KEY (`name_id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB 
  AUTO_INCREMENT=100330 
  DEFAULT CHARSET=utf8mb4 
  COLLATE=utf8mb4_general_ci 
  COMMENT='PlayerbotAI AutoBot names' 
  ROW_FORMAT=Dynamic;

